const paths={
 plus:'M12 5v14M5 12h14',arrow:'M7 17 17 7M7 7h10v10',chevron:'m9 5 7 7-7 7',back:'m14 6-6 6 6 6M8 12h12',close:'m6 6 12 12M6 18 18 6',
 groups:'M9 3H4v5h5zM20 3h-5v5h5zM9 14H4v6h5zM20 14h-5v6h5z',wallet:'M19 7H5a2 2 0 0 1 0-4h13v4M5 7a2 2 0 0 1-2-2v13a2 2 0 0 0 2 2h15V7M20 12h-5v4h5',
 activity:'m3 12 4-1 3-7 4 16 3-8h4',chart:'M4 20V11h4v9M10 20V4h4v16M16 20v-7h4v7',dots:'M5 12h.01M12 12h.01M19 12h.01',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',filter:'M4 7h16M7 12h10M10 17h4',
 food:'M5 3v6a3 3 0 0 0 6 0V3M8 3v18M19 21V3c-4 2-4 7 0 8',home:'m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7',travel:'M4 15h16l-2-6H6l-2 6Zm0 0v5m16-5v5M6 12H3m18 0h-3M7 17h.01M17 17h.01',coffee:'M4 8h12v7a5 5 0 0 1-10 0V8M16 9h2a3 3 0 0 1 0 6h-2M7 3v2m4-2v2M3 21h16',
 check:'m5 12 4 4 10-10',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Zm4 5h6m-6 4h6m-6 4h3',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0V4ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',
 pencil:'m4 16 11-11 4 4L8 20l-5 1 1-5Zm9-9 4 4M15 5l2-2 4 4-2 2',split:'M12 21v-9m0 0L5 5m7 7 7-7M3 5h5M3 5v5m18-5h-5m5 0v5',calendar:'M5 5h14a2 2 0 0 1 2 2v14H3V7a2 2 0 0 1 2-2Zm2-3v6m10-6v6M3 11h18',tag:'M3 3h8l10 10-8 8L3 11V3Zm4 4h.01',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M10 4H4v16h6m5-13 5 5-5 5m-7-5h12',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3l2-2Zm4 5h6'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.receipt}"/></svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const users=['taral','riya','arjun','neha'];
const avatar=(user,size='')=>{const n=Math.max(0,users.indexOf(user));const bg=['#dde3ff','#f8d7b9','#d4e9e2','#eddbf0'][n];const skin=['#c48966','#dca17f','#a76c4a','#b87757'][n];const hair=['M9 18Q7 5 19 7Q30 4 27 19L23 12 11 16Z','M8 28V16Q8 5 19 6Q30 7 29 27L25 22 23 12 13 16 12 27Z','M9 17Q7 4 20 7Q30 8 27 19L23 13 11 15Z','M7 29V16Q8 4 19 5Q32 5 30 29L25 25 24 12 12 17 12 29Z'][n];return`<span class="avatar ${size}" role="img" aria-label="${user}"><svg viewBox="0 0 36 36" aria-hidden="true"><rect width="36" height="36" fill="${bg}"/><path d="M4 36q1-12 14-12t14 12" fill="${['#5365d6','#ed9470','#7e9d78','#9a6a9f'][n]}"/><path d="M15 23h7v7h-7z" fill="${skin}"/><ellipse cx="18" cy="18" rx="9" ry="11" fill="${skin}"/><path d="${hair}" fill="#35303d"/><path d="M14 19h.1m8 0h.1" stroke="#302a36" stroke-width="2" stroke-linecap="round"/><path d="M16 23q2 2 4 0" fill="none" stroke="#733d35" stroke-linecap="round"/></svg></span>`};
const faces=()=>`<span class="avatar-stack">${users.map(u=>avatar(u)).join('')}</span>`;
const money=paise=>{const n=Math.abs(paise);return '₹'+Math.floor(n/100).toLocaleString('en-IN')+'.'+String(n%100).padStart(2,'0')};
function parseMoney(value,zero=false){if(!/^\d{1,9}(?:\.\d{1,2})?$/.test(value))return null;const [a,b='']=value.split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));return Number.isSafeInteger(n)&&(zero?n>=0:n>0)?n:null}
function equalShares(amount,people){const ordered=users.filter(u=>people.includes(u));return Object.fromEntries(ordered.map((u,i)=>[u,Math.floor(amount/ordered.length)+(i<amount%ordered.length?1:0)]))}
const ledger=[
 {id:1,title:'The Anjuna villa',amount:480000,payer:'taral',shares:{taral:180000,riya:120000,arjun:120000,neha:60000},category:'Stay',date:'2026-10-29',creator:'taral',source:'manual'},
 {id:2,title:'Dinner at Thalassa',amount:248050,payer:'neha',shares:equalShares(248050,users),category:'Food',date:'2026-10-30',creator:'neha',source:'manual'},
 {id:3,title:'Scooters for the day',amount:180000,payer:'arjun',shares:equalShares(180000,users),category:'Travel',date:'2026-10-30',creator:'arjun',source:'manual'},
 {id:4,title:'Sunset coffee',amount:62000,payer:'riya',shares:equalShares(62000,['taral','riya','neha']),category:'Food',date:'2026-10-30',creator:'riya',source:'manual'},
 {id:5,title:'Airport to Anjuna',amount:120000,payer:'neha',shares:equalShares(120000,users),category:'Travel',date:'2026-10-29',creator:'neha',source:'manual'}
];
const claims=[{id:1,from:'riya',to:'taral',amount:20000,status:'pending',note:'Sent after lunch'}];
const events=[{user:'riya',title:'marked a payment to you',detail:'₹200.00 · Waiting for your confirmation',time:'Today, 2:42 pm'},{user:'riya',title:'added Sunset coffee',detail:'₹620.00 · Split between 3 people',time:'Today, 2:30 pm'},{user:'arjun',title:'added Scooters for the day',detail:'₹1,800.00 · Split equally',time:'Today, 11:15 am'},{user:'neha',title:'added Dinner at Thalassa',detail:'₹2,480.50 · Split equally',time:'Today, 10:02 am'}];
const categoryMap={Food:['food','', '#ff976c'],Travel:['travel','travel','#65aab6'],Stay:['home','stay','#7882dc'],Other:['receipt','stay','#b9a0d9'],Shopping:['tag','', '#e4b36b'],Utilities:['home','travel','#65aab6'],Entertainment:['sun','coffee','#e4b36b']};
let current='home',groupTab='expenses',search='',category='',viewId=2,flat=false,editId=null;
let draft={title:'Dinner at the beach',amount:'1240.00',date:'2026-10-30',payer:'taral',category:'Food',tag:'',mode:'equal',selected:[...users],exact:Object.fromEntries(users.map(u=>[u,'310.00']))};
let receiptPeople=[...users];const receiptItems=[{title:'Wood-fired pizzas',amount:56000,people:[...users]},{title:'Pasta for the table',amount:40000,people:[...users]},{title:'Lime sodas',amount:28000,people:[...users]}];
const main=document.querySelector('#main'),nav=document.querySelector('.bottom-nav'),sheet=document.querySelector('#sheet');
function balances(){const b=Object.fromEntries(users.filter(u=>u!=='taral').map(u=>[u,0]));for(const e of ledger){if(e.payer==='taral'){for(const [u,n]of Object.entries(e.shares))if(u!=='taral')b[u]+=n}else b[e.payer]-=e.shares.taral||0}for(const c of claims.filter(c=>c.status==='confirmed')){if(c.to==='taral')b[c.from]-=c.amount;if(c.from==='taral')b[c.to]+=c.amount}return b}
const total=()=>ledger.reduce((a,e)=>a+e.amount,0);
const net=()=>Object.values(balances()).reduce((a,n)=>a+n,0);
const paid=()=>ledger.filter(e=>e.payer==='taral').reduce((a,e)=>a+e.amount,0);
const share=()=>ledger.reduce((a,e)=>a+(e.shares.taral||0),0);
const pendingToMe=()=>claims.filter(c=>c.to==='taral'&&c.status==='pending');
function navigation(){const active=['group','detail','insights','receipt'].includes(current)?'home':current;nav.hidden=['add','receipt','voice'].includes(current);nav.innerHTML=`<button data-go="home" ${active==='home'?'aria-current="page"':''}>${icon('groups')}<span>Groups</span></button><button data-go="balances" ${active==='balances'?'aria-current="page"':''}>${icon('wallet')}<span>Balances</span></button><button class="nav-add" data-action="add-sheet" aria-label="Add an expense">${icon('plus')}</button><button data-go="activity" ${active==='activity'?'aria-current="page"':''}>${icon('activity')}<span>Activity</span>${pendingToMe().length?'<i class="nav-notice"></i>':''}</button><button data-action="more-sheet">${icon('dots')}<span>More</span></button>`}
function header(title,subtitle='',back='home',action=''){return`<header class="simple-header"><button class="icon-button white" data-go="${back}" aria-label="Go back">${icon('back')}</button><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</header>`}
function footerNote(){return`<p class="prototype-tag">Interactive concept · Sample data · INR only</p>`}
function home(){const b=balances(),owed=Object.values(b).filter(n=>n>0).reduce((a,n)=>a+n,0),owe=-Object.values(b).filter(n=>n<0).reduce((a,n)=>a+n,0);return`<header class="topbar"><a class="wordmark" href="#home"><span class="logomark">${icon('split')}</span>broYouOweMe<span style="color:var(--blue)">.</span></a><button class="icon-button" data-action="profile" aria-label="Your account">${avatar('taral')}</button></header><div class="greeting"><div><p>A little less “who paid?”</p><h1>Hey, taral ${icon('sun')}</h1></div><span class="date-chip">Fri, 30 Oct</span></div><section class="balance-card" aria-label="Your overall balance"><div class="balance-top"><span>${net()>=0?'You’re owed overall':'You owe overall'}</span><span class="badge">Across 2 groups</span></div><div class="net"><strong class="money">${money(net())}</strong><button class="balance-arrow" data-go="balances" aria-label="View balance breakdown">${icon('arrow')}</button></div><div class="balance-parts"><div><small><i class="dot"></i>You’re owed</small><strong class="money">${money(owed)}</strong></div><div><small><i class="dot orange"></i>You owe</small><strong class="money">${money(owe)}</strong></div></div></section>${pendingToMe().length?`<button class="pending-strip" data-go="settle">${avatar('riya')}<div><strong>riya marked ${money(pendingToMe()[0].amount)} paid</strong><small>Received it? Give it a quick check.</small></div>${icon('chevron')}</button>`:''}<div class="section-heading"><h2>Your circles <small style="font-family:inherit;font-size:12px;font-weight:400">2</small></h2><button class="text-button" data-action="create-group">＋ New group</button></div><button class="photo-group" data-group="goa"><div class="group-photo"><img src="assets/goa.jpg" alt="Palm-lined beach in Goa"><span class="photo-badge">The weekend crew</span><div class="group-name"><h3>Goa, finally.</h3><p>4 people · ${ledger.length} shared expenses</p></div></div><div class="group-foot"><div><small>${net()>=0?'You’re owed':'You owe'}</small><strong class="money ${net()<0?'negative':''}">${money(net())}</strong></div>${faces()}</div></button><button class="compact-group" data-group="flat"><span class="group-tile">${icon('home')}</span><div><h3>Flat 402</h3><p>3 flatmates · Home base</p></div><span class="settled">${icon('check')}All settled</span></button><div class="home-latest"><div class="section-heading"><h2>Fresh on the tab</h2><button class="text-button" data-go="activity">See activity</button></div><div class="expense-feed">${expenseRow(ledger[ledger.length-1])}</div></div>${footerNote()}`}
function expenseRow(e){const c=categoryMap[e.category]||categoryMap.Other;const mine=e.payer==='taral'?e.amount-(e.shares.taral||0):-(e.shares.taral||0);return`<button class="expense-row" data-detail="${e.id}"><span class="expense-icon ${c[1]}">${icon(e.title.toLowerCase().includes('coffee')?'coffee':c[0])}</span><span class="expense-text"><strong>${esc(e.title)}</strong><small>${e.payer==='taral'?'You':e.payer} paid · ${Object.keys(e.shares).length} people</small></span><span class="expense-cost"><strong class="money">${money(e.amount)}</strong><small class="${mine>0?'positive':mine<0?'negative':''}">${mine>0?'you lent ':mine<0?'your share ':'not in this split '}${money(mine)}</small></span></button>`}
function group(){return`<section class="group-hero"><img src="assets/goa.jpg" alt="Palm-lined Goa beach"><div class="topbar"><button class="icon-button" data-go="home" aria-label="Back to your groups">${icon('back')}</button><button class="icon-button" data-action="group-menu" aria-label="Group options">${icon('dots')}</button></div><div class="hero-meta"><h1>Goa, finally.</h1><p>Good company. Questionable decisions.</p><div class="group-meta-row">${faces()}<small>4 people, one shared tab</small></div></div></section><section class="group-summary"><div class="group-summary-top"><div><p>${net()>=0?'You’re owed in this group':'You owe in this group'}</p><strong class="money ${net()>=0?'positive':'negative'}">${money(net())}</strong></div><button class="settle-mini" data-go="settle">Settle up ${icon('arrow')}</button></div><p class="group-stats">Group spent <strong class="money">${money(total())}</strong><span>·</span><span>${ledger.length} expenses</span></p><nav class="segmented" aria-label="Goa group sections"><button data-tab="expenses" ${groupTab==='expenses'?'aria-current="page"':''}>Expenses</button><button data-tab="balances" ${groupTab==='balances'?'aria-current="page"':''}>Balances</button><button data-go="insights">Insights</button><button data-action="members">People</button></nav></section>${groupTab==='expenses'?`<div class="feed-tools"><label class="search-box">${icon('search')}<input id="search" type="search" placeholder="Find an expense" aria-label="Search group expenses" value="${esc(search)}"></label><button class="filter-button ${category?'active':''}" data-action="filter" aria-label="Filter expense category">${icon('filter')}</button></div><div id="feed">${feed()}</div>`:`<div class="section-heading"><h2>Who owes whom</h2><span class="badge">Your balances</span></div>${peopleBalances()}<p class="context-note">${icon('info')}These are your pairwise debts in this group. Suggested minimum-transfer payments can differ from debts you can claim.</p><button class="secondary full" data-go="settle">Review payment claims ${icon('chevron')}</button>`}<p class="feed-footer">${icon('shield')}Every share, down to the last paisa.</p>`}
function feed(){const filtered=[...ledger].reverse().filter(e=>e.title.toLowerCase().includes(search.toLowerCase())&&(!category||e.category===category));if(!filtered.length)return`<div class="empty"><h2>No bills found</h2><p>Try another search or clear the category filter.</p><button class="text-button" data-action="clear-filter">Clear filters</button></div>`;return['2026-10-30','2026-10-29'].map(date=>{const rows=filtered.filter(e=>e.date===date);return rows.length?`<div class="day-label"><span>${date==='2026-10-30'?'Today, 30 October':'Yesterday, 29 October'}</span><span>${money(rows.reduce((a,e)=>a+e.amount,0))}</span></div><div class="expense-feed">${rows.map(expenseRow).join('')}</div>`:''}).join('')+filtered.filter(e=>!['2026-10-30','2026-10-29'].includes(e.date)).map(e=>`<div class="day-label"><span>${esc(e.date)}</span></div><div class="expense-feed">${expenseRow(e)}</div>`).join('')}
function peopleBalances(){const b=balances();return`<div class="balance-people">${users.filter(u=>u!=='taral').map(u=>`<button class="person-row full" data-person="${u}" style="text-align:left">${avatar(u,'large')}<span class="who"><strong>${b[u]>=0?u+' owes you':'You owe '+u}</strong><small>${claims.filter(c=>c.status==='pending'&&((c.from===u&&c.to==='taral')||(c.from==='taral'&&c.to===u))).map(c=>money(c.amount)+' pending').join(', ')||'No pending payments'}</small></span><strong class="money ${b[u]>=0?'positive':'negative'}">${money(b[u])}</strong>${icon('chevron')}</button>`).join('')}</div>`}
function balancesPage(){return`${header('Your balances','Across your groups')}<div class="screen-intro"><h1>All on the table.</h1><p>Every balance stays with its group. Confirmed payments are reflected here.</p></div><div class="section-heading"><h2>Goa, finally.</h2><button class="text-button" data-group="goa">Open group</button></div>${peopleBalances()}<button class="primary full" style="margin-top:18px" data-go="settle">Review payments ${icon('arrow')}</button><div class="section-heading"><h2>Flat 402</h2><span class="settled">${icon('check')}All settled</span></div><p class="context-note">${icon('shield')}Pending claims do not change your balances.</p>`}
function sharesForDraft(){const amount=parseMoney(draft.amount);return{amount,shares:draft.mode==='equal'?(amount&&draft.selected.length?equalShares(amount,draft.selected):{}):Object.fromEntries(users.filter(u=>draft.selected.includes(u)).map(u=>[u,parseMoney(draft.exact[u],true)??-1]))}}
function sharePreview(){const {amount,shares}=sharesForDraft();const sum=Object.values(shares).reduce((a,n)=>a+Math.max(0,n),0);const remaining=(amount||0)-sum;return`<div class="participant-card">${users.map(u=>`<div class="participant-row"><label><input type="checkbox" data-participant="${u}" ${draft.selected.includes(u)?'checked':''}>${avatar(u)}<span>${u}${u==='taral'?' (you)':''}</span></label>${draft.mode==='equal'?`<span class="money">${money(shares[u]||0)}</span>`:`<input class="share-input" inputmode="decimal" aria-label="${u}’s share in INR" data-exact="${u}" value="${esc(draft.exact[u])}" ${draft.selected.includes(u)?'':'disabled'}>`}</div>`).join('')}</div><div class="split-check" id="split-check"><span>${icon(remaining===0?'check':'info')}<span>${!draft.selected.length?'Select at least one person':remaining===0?'Every paisa accounted for':remaining>0?money(remaining)+' left to assign':money(-remaining)+' over the total'}</span></span><strong class="money">${money(sum)}</strong></div>`}
function add(){return`${header(editId?'Edit expense':'Add an expense','Goa, finally.','group')}<div class="method-tabs"><button aria-pressed="true">${icon('pencil')}Type it</button><button data-go="receipt">${icon('receipt')}Receipt</button><button data-go="voice">${icon('mic')}Voice</button></div><form id="expense-form"><div class="amount-entry"><label for="amount">How much was it?</label><div class="amount-wrap"><span>₹</span><input id="amount" name="amount" aria-label="Amount in INR" inputmode="decimal" maxlength="12" value="${esc(draft.amount)}" required pattern="[0-9]+([.][0-9]{1,2})?"></div><span class="badge">INR · Indian rupee</span></div><div class="form-card"><label class="sr-only" for="description" style="display:block;font-size:10px;color:var(--muted);padding-top:13px">What was it for?</label><input class="description-input" id="description" required maxlength="200" value="${esc(draft.title)}" placeholder="e.g. Dinner at the beach"><div class="field-line">${icon('wallet')}<label for="payer">Paid by</label><select id="payer">${users.map(u=>`<option value="${u}" ${u===draft.payer?'selected':''}>${u==='taral'?'You (taral)':u}</option>`).join('')}</select></div><div class="field-line">${icon('tag')}<label for="category">Category</label><select id="category">${Object.keys(categoryMap).map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field-line">${icon('calendar')}<label for="date">Date</label><input id="date" type="date" value="${draft.date}" required></div></div><div class="split-heading"><h2>Split the bill</h2><div class="split-tabs" aria-label="Split method"><button type="button" data-split="equal" aria-pressed="${draft.mode==='equal'}">Equally</button><button type="button" data-split="exact" aria-pressed="${draft.mode==='exact'}">Exact amounts</button></div></div><div id="share-preview">${sharePreview()}</div><p class="context-note">${icon('info')}Only selected people share this bill. The payer can be outside the split.</p><details style="font-size:11px;margin:12px 0"><summary>More details</summary><label class="sheet-field">Tag (optional)<input id="expense-tag" value="${esc(draft.tag)}" placeholder="e.g. beach day"></label></details><p class="form-error" id="expense-error" role="alert"></p><div class="composer-footer"><button class="primary full" type="submit"><span>${editId?'Save changes':'Add expense'}</span><strong class="money" id="save-amount">${money(parseMoney(draft.amount)||0)}</strong>${icon('arrow')}</button><p>Prototype only. No real group or ledger is connected.</p></div></form>`}
function settle(){const c=claims.find(c=>c.to==='taral'&&c.from==='riya');const outstanding=balances().riya;return`${header('Settle up','Goa, finally.','group')}<div class="screen-intro"><h1>A little closure.</h1><p>Review payments, then get back to the good stuff.</p></div>${c?`<section class="review-card"><div class="review-card-top"><div class="person-row">${avatar('riya','large')}<div class="who"><strong>riya ${c.status==='pending'?'says she paid you':c.status==='confirmed'?'paid you':'sent a claim'}</strong><small>Today, 2:42 pm</small></div><span class="badge ${c.status==='pending'?'pending':c.status==='confirmed'?'confirmed':''}">${c.status==='pending'?'Needs your review':c.status==='confirmed'?'Confirmed':'Rejected'}</span></div><span class="money big">${money(c.amount)}</span><p>Goa, finally. · Payment claim</p></div><div class="review-card-body"><p class="quoted">“${esc(c.note)}”</p><div class="debt-explainer"><small>riya’s current debt to you</small><strong class="money">${money(outstanding)}</strong></div><div class="debt-explainer"><small>${c.status==='pending'?'After you confirm receipt':'Claim status'}</small><strong class="money">${c.status==='pending'?money(outstanding-c.amount):c.status}</strong></div>${c.status==='pending'?`<div class="review-actions"><button class="secondary" data-claim="reject">Not received</button><button class="primary" data-claim="confirm">${icon('check')}Yes, received</button></div>`:''}</div></section>`:''}<p class="context-note">${icon('shield')}Only confirm money you’ve actually received. A pending claim never changes a balance.</p><div class="section-heading"><h2>Your payments</h2></div>${Object.entries(balances()).filter(([,n])=>n<0).map(([u,n])=>`<button class="claim-option" data-person="${u}">${avatar(u)}<span class="who"><strong>You owe ${u}</strong><small>Already paid? Record a claim.</small></span><strong class="money negative">${money(n)}</strong>${icon('chevron')}</button>`).join('')||'<div class="empty">You don’t owe anyone in this group.</div>'}${claims.filter(c=>c.from==='taral').map(c=>`<div class="claim-option">${icon('wallet')}<div class="who"><strong>${money(c.amount)} to ${c.to}</strong><small>Awaiting ${c.to}’s confirmation · ${esc(c.note||'No note')}</small></div><span class="badge pending">Pending</span></div>`).join('')}<p class="prototype-tag">Records only. No money moves through this app.</p>`}
function receipt(){return`${header('Review receipt','Goa, finally. · Sample scan','group')}<div class="screen-intro"><h1>Who had what?</h1><p>Check the bill and tap who’s sharing each item.</p></div><div class="receipt-paper"><span class="receipt-mark">${icon('food')}</span><h2>The beach café</h2><p>30 October 2026 · Paid by you</p><div class="receipt-rule"></div>${receiptItems.map((item,i)=>`<div class="receipt-item"><div><strong>${item.title}</strong><small>Split among ${item.people.length||0} ${item.people.length===1?'person':'people'}</small><div class="payee-chips">${users.map(u=>`<button class="payee-chip" data-receipt-item="${i}" data-payee="${u}" aria-label="${u} shares ${item.title}" aria-pressed="${item.people.includes(u)}">${u==='taral'?'You':u}</button>`).join('')}</div></div><span class="money">${money(item.amount)}</span></div>`).join('')}<div class="receipt-total"><span>Receipt total</span><span class="money">₹1,240.00</span></div></div><div class="section-heading" style="margin-top:28px"><h2>The split</h2><span class="badge">Itemised</span></div><div class="balance-people">${Object.entries(receiptAllocation()).map(([u,n])=>`<div class="person-row">${avatar(u)}<span class="who"><strong>${u==='taral'?'You':u}</strong></span><strong class="money">${money(n)}</strong></div>`).join('')}</div><label class="review-approval"><input id="receipt-approval" type="checkbox"><span>I’ve checked the items, people and total, and approve this expense.</span></label><p class="form-error" id="receipt-error" role="alert"></p><div class="composer-footer"><button class="primary full" id="approve-receipt">Approve & add expense ${icon('arrow')}</button><p>Sample receipt only. Nothing is uploaded or saved to the app.</p></div>`}
function receiptAllocation(){const result=Object.fromEntries(users.map(u=>[u,0]));for(const item of receiptItems){const shares=equalShares(item.amount,item.people.length?item.people:users);for(const [u,n]of Object.entries(shares))result[u]+=n}return result}
function insights(){const categories=Object.entries(ledger.reduce((r,e)=>{r[e.category]=(r[e.category]||0)+e.amount;return r},{})).sort((a,b)=>b[1]-a[1]);return`${header('Trip insights','Goa, finally.','group','<select class="month-select" aria-label="Report month"><option>Oct 2026</option></select>')}<section class="insights-total"><p>The group spent</p><strong class="money">${money(total())}</strong><div class="category-bar" role="img" aria-label="Spending by category; exact values listed below">${categories.map(([c,n])=>`<span style="width:${n/total()*100}%;background:${categoryMap[c][2]}"></span>`).join('')}</div><div class="legend">${categories.map(([c])=>`<span style="--swatch:${categoryMap[c][2]}"><i></i>${c}</span>`).join('')}</div></section><div class="info-pairs"><div><dt>Your share</dt><dd class="money">${money(share())}</dd></div><div><dt>You paid</dt><dd class="money">${money(paid())}</dd></div></div><div class="section-heading"><h2>Where it all went</h2></div><div class="expense-feed">${categories.map(([c,n])=>`<div class="insight-row"><span class="expense-icon ${categoryMap[c][1]}">${icon(categoryMap[c][0])}</span><div><strong>${c}</strong><small>${ledger.filter(e=>e.category===c).length} expenses · ${(n/total()*100).toFixed(1)}% of trip</small></div><strong class="money">${money(n)}</strong></div>`).join('')}</div><div class="bar-chart"><h2>The weekend, in bills</h2><div class="bars">${['2026-10-29','2026-10-30'].map(d=>{const n=ledger.filter(e=>e.date===d).reduce((a,e)=>a+e.amount,0);return`<div class="bar-col"><small class="money">${money(n)}</small><span class="bar" style="height:${Math.max(4,n/total()*105)}px"></span><span>${d==='2026-10-29'?'29 Oct':'30 Oct'}</span></div>`}).join('')}</div></div><button class="secondary full" data-action="export">${icon('download')}Export this trip (CSV)</button><p class="context-note">${icon('info')}This concept shows the current trip. The app’s month filter and selected/all-date exports remain part of the full design.</p>`}
function detail(){const e=ledger.find(e=>e.id===viewId)||ledger[0];const c=categoryMap[e.category]||categoryMap.Other;return`${header('The bill','Goa, finally.','group',e.creator==='taral'?`<button class="icon-button white" data-edit="${e.id}" aria-label="Edit expense">${icon('pencil')}</button>`:'')}<div class="detail-hero"><span class="expense-icon ${c[1]}">${icon(c[0])}</span><h1>${esc(e.title)}</h1><strong class="money">${money(e.amount)}</strong><p>Paid by ${e.payer==='taral'?'you':e.payer} · ${esc(e.date)}</p></div><dl class="info-pairs"><div><dt>Category</dt><dd>${e.category}</dd></div><div><dt>Added by</dt><dd>${e.creator==='taral'?'You':e.creator}</dd></div><div><dt>Entry method</dt><dd>${e.source==='ocr'?'Receipt, reviewed':e.source==='voice'?'Voice, reviewed':'Manually entered'}</dd></div>${e.tag?`<div><dt>Tag</dt><dd>${esc(e.tag)}</dd></div>`:''}</dl><div class="section-heading"><h2>Everyone’s share</h2><span class="badge">${e.source==='ocr'?'Itemised':'Exact to the paisa'}</span></div><div class="balance-people">${Object.entries(e.shares).map(([u,n])=>`<div class="person-row">${avatar(u)}<span class="who"><strong>${u==='taral'?'You':u}</strong><small>${e.payer===u?'Paid the bill':'Participant'}</small></span><strong class="money">${money(n)}</strong></div>`).join('')}</div>${e.items?`<div class="section-heading"><h2>Receipt items</h2></div><div class="info-pairs">${e.items.map(item=>`<div><span>${item.title}<small style="display:block">${(item.people.length?item.people:users).join(', ')}</small></span><strong class="money">${money(item.amount)}</strong></div>`).join('')}</div>`:''}<p class="context-note">${icon('shield')}${e.creator==='taral'?'You created this bill. Changes update everyone’s shares.':'Only '+e.creator+' can edit or delete this expense.'}</p>${e.creator==='taral'?`<button class="secondary full" data-edit="${e.id}">${icon('pencil')}Edit expense</button><button class="text-button full" style="color:var(--red);margin-top:10px" data-delete="${e.id}">Delete this preview expense</button>`:''}`}
function activity(){return`${header('Group activity','Goa, finally.')}<div class="screen-intro"><h1>The running tab.</h1><p>Who added what, and what changed.</p></div><div class="timeline">${events.map(e=>`<article class="event">${avatar(e.user)}<div><strong>${e.user} ${esc(e.title)}</strong><p>${esc(e.detail)}</p><time>${e.time}</time></div></article>`).join('')}</div><p class="context-note">${icon('shield')}A shared record helps everyone stay on the same page.</p>`}
function voice(){return`${header('Say it. Split it.','Goa, finally.','group')}<div class="screen-intro"><h1>Keep the story short.</h1><p>Say who paid, what it cost, and who was in.</p></div><div class="voice-area"><span class="expense-icon stay" style="margin-bottom:18px">${icon('mic')}</span><label for="transcript">Example transcript</label><textarea id="transcript">I paid 1240 rupees for dinner at the beach. Split between all four of us.</textarea><button class="primary full" data-action="voice-review">Review the sample expense ${icon('arrow')}</button><p>This preview uses the fixed example above. Live recording and parsing belong to the connected app. You’ll review the result before saving.</p></div>`}
function flatGroup(){return`${header('Flat 402','3 flatmates · All settled')}<div class="empty" style="padding-top:60px"><span class="group-tile">${icon('home')}</span><h2>Home base, fresh start.</h2><p>No bills here yet.<br>Your first shared grocery run belongs here.</p><button class="secondary" data-go="home">Back to your groups</button></div>`}
function render(focus=false){const screens={home,group:flat?flatGroup:group,balances:balancesPage,add,settle,receipt,insights,detail,activity,voice};main.innerHTML=(screens[current]||home)();navigation();document.title=({home:'Your circles',group:flat?'Flat 402':'Goa, finally.',add:'Add expense',settle:'Settle up',receipt:'Review receipt',insights:'Trip insights',balances:'Your balances',detail:'The bill',activity:'Activity',voice:'Voice review'}[current]||'Your circles')+' · BroYouOweMe';if(focus){window.scrollTo(0,0);main.focus({preventScroll:true})}}
function go(page){if(sheet.open)sheet.close();if(location.hash.slice(1)===page){current=page;render(true)}else location.hash=page}
function openSheet(title,body){sheet.innerHTML=`<div class="sheet-handle"></div><header class="sheet-heading"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close-sheet" aria-label="Close dialog">${icon('close')}</button></header>${body}`;sheet.showModal()}
function option(title,sub,symbol,attrs=''){return`<button class="sheet-option" ${attrs}><span class="expense-icon ${symbol==='mic'?'stay':symbol==='receipt'?'coffee':'travel'}">${icon(symbol)}</span><div><strong>${title}</strong><small>${sub}</small></div>${icon('chevron')}</button>`}
let toastTimer;function toast(message){const t=document.querySelector('.toast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4500)}
function groupMenu(){openSheet('The group stuff.',option('People','4 friends · taral is an admin','groups','data-action="members"')+option('Invite friends','Link and QR invitations · Admin only','plus','data-action="invites"')+option('Categories','Keep every bill in the right place','tag','data-action="categories"')+option('Payment reminders','Review a message before sharing','bell','data-action="reminders"'))}
function showPerson(u){const b=balances()[u],toMe=b>=0;const pending=claims.filter(c=>c.status==='pending'&&(toMe?c.from===u&&c.to==='taral':c.from==='taral'&&c.to===u)).reduce((a,c)=>a+c.amount,0);const available=Math.max(0,Math.abs(b)-pending);openSheet(toMe?u+' owes you':'You owe '+u,`<div class="person-row">${avatar(u,'large')}<div class="who"><strong>Goa, finally.</strong><small>${toMe?'They owe you':'You owe them'} ${money(b)}</small></div></div><div class="debt-explainer"><small>Pending claims</small><strong class="money">${money(pending)}</strong></div><div class="debt-explainer"><small>Available to claim</small><strong class="money">${money(available)}</strong></div>${toMe?`<p class="context-note">${icon('info')}${u} records a payment after paying you. You confirm it once received.</p><button class="primary full" data-go="settle">Review received claims</button>`:`<form id="claim-form" data-to="${u}" data-max="${available}"><label class="sheet-field">How much did you pay? (INR)<input id="claim-amount" inputmode="decimal" value="${(available/100).toFixed(2)}" pattern="[0-9]+([.][0-9]{1,2})?" required></label><label class="sheet-field">Note (optional)<input id="claim-note" placeholder="e.g. Paid after dinner" maxlength="200"></label><p id="claim-error" class="form-error" role="alert"></p><button class="primary full" ${available?'':'disabled'}>Record payment claim</button><p class="context-note">${icon('shield')}Your debt changes only after ${u} confirms receipt. No money is transferred.</p></form>`}`)}
function saveExpense(){const {amount,shares}=sharesForDraft();if(!draft.title.trim()||!amount||!draft.date||!draft.selected.length||Object.values(shares).some(n=>n<0)||Object.values(shares).reduce((a,n)=>a+n,0)!==amount){document.querySelector('#expense-error').textContent='Add a description and valid amount, select people, and make every share add up to the bill.';return}const e={id:editId||Math.max(0,...ledger.map(e=>e.id))+1,title:draft.title.trim(),amount,payer:draft.payer,shares,category:draft.category,date:draft.date,creator:'taral',source:editId?(ledger.find(e=>e.id===editId)?.source||'manual'):'manual',tag:draft.tag};const old=ledger.findIndex(e=>e.id===editId);if(old>=0)ledger[old]=e;else ledger.push(e);events.unshift({user:'taral',title:(editId?'edited ':'added ')+e.title,detail:money(amount)+' · '+Object.keys(shares).length+' participants',time:'Just now'});editId=null;search='';category='';groupTab='expenses';flat=false;go('group');toast('Saved to the preview. Balances and insights updated.')}
function syncDraft(){const {amount,shares}=sharesForDraft();document.querySelector('#save-amount').textContent=money(amount||0);if(draft.mode==='equal')document.querySelector('#share-preview').innerHTML=sharePreview();else{const sum=Object.values(shares).reduce((a,n)=>a+Math.max(n,0),0);document.querySelector('#split-check').innerHTML=`<span>${icon(sum===amount?'check':'info')}${sum===amount?'Every paisa accounted for':sum<(amount||0)?money((amount||0)-sum)+' left to assign':money(sum-(amount||0))+' over the total'}</span><strong class="money">${money(sum)}</strong>`}}
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;document.querySelector('#feed').innerHTML=feed();return}if(current==='add'){const mapping={amount:'amount',description:'title',date:'date',payer:'payer',category:'category','expense-tag':'tag'};if(mapping[e.target.id]){draft[mapping[e.target.id]]=e.target.value;if(e.target.id==='amount')syncDraft()}if(e.target.dataset.exact){draft.exact[e.target.dataset.exact]=e.target.value;syncDraft()}}});
document.addEventListener('change',e=>{if(e.target.dataset.participant){const u=e.target.dataset.participant;draft.selected=e.target.checked?[...new Set([...draft.selected,u])]:draft.selected.filter(v=>v!==u);document.querySelector('#share-preview').innerHTML=sharePreview()}});
document.addEventListener('submit',e=>{if(e.target.id==='expense-form'){e.preventDefault();saveExpense()}if(e.target.id==='claim-form'){e.preventDefault();const amount=parseMoney(document.querySelector('#claim-amount').value),max=Number(e.target.dataset.max),to=e.target.dataset.to;if(!amount||amount>max){document.querySelector('#claim-error').textContent='Enter an amount from ₹0.01 to '+money(max)+'.';return}claims.push({id:claims.length+1,from:'taral',to,amount,status:'pending',note:document.querySelector('#claim-note').value});events.unshift({user:'taral',title:'recorded a payment to '+to,detail:money(amount)+' · Awaiting confirmation',time:'Just now'});sheet.close();go('settle');toast('Claim recorded in the preview. Your debt is unchanged.')}});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-go]');if(!b)return;if(b.dataset.go){if(b.dataset.go==='add')editId=null;go(b.dataset.go);return}if(b.dataset.group){flat=b.dataset.group==='flat';groupTab='expenses';go('group');return}if(b.dataset.tab){groupTab=b.dataset.tab;render();return}if(b.dataset.detail){viewId=Number(b.dataset.detail);go('detail');return}if(b.dataset.person){showPerson(b.dataset.person);return}if(b.dataset.split){draft.mode=b.dataset.split;const {amount}=sharesForDraft();if(draft.mode==='exact'&&amount){const shares=equalShares(amount,draft.selected);for(const u of users)draft.exact[u]=((shares[u]||0)/100).toFixed(2)}render();return}if(b.dataset.edit){const e=ledger.find(e=>e.id===Number(b.dataset.edit));if(e.creator!=='taral')return;editId=e.id;draft={title:e.title,amount:(e.amount/100).toFixed(2),date:e.date,payer:e.payer,category:e.category,tag:e.tag||'',mode:'exact',selected:Object.keys(e.shares),exact:Object.fromEntries(users.map(u=>[u,((e.shares[u]||0)/100).toFixed(2)]))};go('add');return}if(b.dataset.delete){const id=Number(b.dataset.delete);openSheet('Delete this bill?',`<p class="context-note">This removes the fictional expense from this preview and recalculates its balances.</p><button class="primary full" data-delete-confirm="${id}" style="background:var(--red)">Delete preview expense</button>`);return}if(b.dataset.deleteConfirm){const i=ledger.findIndex(e=>e.id===Number(b.dataset.deleteConfirm)&&e.creator==='taral');if(i>=0)ledger.splice(i,1);sheet.close();go('group');toast('Removed from this preview. Balances updated.');return}if(b.dataset.claim){const c=claims.find(c=>c.id===1);if(c.status!=='pending')return;c.status=b.dataset.claim==='confirm'?'confirmed':'rejected';events.unshift({user:'taral',title:c.status+' riya’s payment',detail:money(c.amount)+(c.status==='confirmed'?' · Balance updated':' · Balance unchanged'),time:'Just now'});render();toast(c.status==='confirmed'?'Receipt confirmed in preview. Balance updated.':'Claim rejected in preview. Balance unchanged.');return}if(b.dataset.receiptItem!==undefined){const item=receiptItems[Number(b.dataset.receiptItem)],u=b.dataset.payee;item.people=item.people.includes(u)?item.people.filter(p=>p!==u):[...item.people,u];render();return}if(b.id==='approve-receipt'){if(!document.querySelector('#receipt-approval').checked){document.querySelector('#receipt-error').textContent='Check the items and split, then tick the approval box.';return}const e={id:Math.max(...ledger.map(e=>e.id))+1,title:'The beach café',amount:124000,payer:'taral',shares:receiptAllocation(),category:'Food',date:'2026-10-30',creator:'taral',source:'ocr',items:receiptItems.map(i=>({...i,people:[...i.people]}))};ledger.push(e);events.unshift({user:'taral',title:'approved The beach café receipt',detail:'₹1,240.00 · Itemised shares',time:'Just now'});viewId=e.id;go('detail');toast('Reviewed sample added to this preview.');return}
const action=b.dataset.action;if(action==='close-sheet')sheet.close();if(action==='add-sheet')openSheet('Add it to the tab.',option('Type an expense','Amount, who paid, and who’s in.','pencil','data-go="add"')+option('Scan a receipt','Check items and assign everyone’s share.','receipt','data-go="receipt"')+option('Say it out loud','A quick transcript, then your review.','mic','data-go="voice"')+'<p class="sheet-caption">For Goa, finally. · You approve every expense.</p>');
if(action==='more-sheet')openSheet('The other good stuff.',option('Trip insights','Where the shared money went','chart','data-go="insights"')+option('Group options','People, invites, categories and reminders','groups','data-action="group-menu"')+option('Your account','taral · Sample profile','shield','data-action="profile"'));
if(action==='group-menu')groupMenu();
if(action==='profile')openSheet('Hey, taral.',`<div class="person-row">${avatar('taral','large')}<div class="who"><strong>taral</strong><small>Sample account · 2 circles</small></div><span class="badge">Prototype</span></div><p class="context-note">${icon('shield')}This is a local design prototype. No account is connected.</p>`);
if(action==='members')openSheet('The weekend crew.',`<div class="balance-people">${users.map(u=>`<div class="person-row">${avatar(u)}<div class="who"><strong>${u}${u==='taral'?' (you)':''}</strong><small>${u==='taral'?'Group admin':'Member'}</small></div></div>`).join('')}</div><p class="context-note">${icon('info')}Role changes and removal remain the separate functional gap F1 from the audit.</p>`);
if(action==='filter')openSheet('Find your kind of bill.',['','Food','Stay','Travel'].map(c=>option(c||'All categories',c===category?'Currently selected':'Filter the trip’s expenses',categoryMap[c]?.[0]||'receipt',`data-filter="${c||'all'}"`)).join(''));
if(b.dataset.filter){category=b.dataset.filter==='all'?'':b.dataset.filter;sheet.close();render()}
if(action==='clear-filter'){search='';category='';render()}
if(action==='create-group')openSheet('A new circle.',`<p class="context-note">This study focuses on your existing groups. The connected app’s group-creation form will use the same fields and controls.</p><label class="sheet-field">Group name<input placeholder="e.g. The Sunday crew" maxlength="100"></label><p class="sheet-caption">Design preview. Group creation is not connected here.</p>`);
if(action==='invites')openSheet('Bring your people.',`<div class="group-tile" style="margin-bottom:16px">${icon('plus')}</div><p class="context-note">Admin-only invite links and QR codes will live here. Existing links expire after 7 days. No invite is created by this preview.</p>`);
if(action==='categories')openSheet('A place for every bill.',`<div class="balance-people">${Object.entries(categoryMap).map(([c,v])=>`<div class="person-row"><span class="expense-icon ${v[1]}">${icon(v[0])}</span><div class="who"><strong>${c}</strong><small>Built-in category</small></div></div>`).join('')}</div>`);
if(action==='reminders')openSheet('A friendly reminder.',`<p class="context-note">Review the debt and pending amount before choosing to share a message.</p><div class="review-card-body" style="background:white;border-radius:15px;font-size:12px;line-height:1.8">Hey arjun, the Goa tab shows ${money(balances().arjun)} owed to me. Could you settle it when you get a chance?</div><p class="sheet-caption">Sample copy only. No message is sent or shared.</p>`);
if(action==='voice-review'){draft={title:'Dinner at the beach',amount:'1240.00',date:'2026-10-30',payer:'taral',category:'Food',tag:'',mode:'equal',selected:[...users],exact:Object.fromEntries(users.map(u=>[u,'310.00']))};editId=null;go('add');toast('Fixed sample loaded. Check every field before adding.')}
if(action==='export'){const rows=[['Description','Payer','Amount (INR)','Date','Category'],...ledger.map(e=>[e.title,e.payer,(e.amount/100).toFixed(2),e.date,e.category])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='goa-preview.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded the fictional trip’s CSV.')}
});
const allowed=['home','group','balances','add','settle','receipt','insights','detail','activity','voice'];
window.addEventListener('hashchange',()=>{current=allowed.includes(location.hash.slice(1))?location.hash.slice(1):'home';render(true)});
current=allowed.includes(location.hash.slice(1))?location.hash.slice(1):'home';render();
